--
-- Table structure for table `customer_admin_question_answers`
--

CREATE TABLE `customer_admin_question_answers` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `unique_id` varchar(191) NOT NULL,
  `answer_delivery_text` varchar(191) NOT NULL,
  `answer_return_text` varchar(191) NOT NULL,
  `delivery_amt` decimal(8,2) NOT NULL DEFAULT 0.00,
  `return_amt` decimal(8,2) NOT NULL DEFAULT 0.00,
  `required` tinyint(1) NOT NULL DEFAULT 0,
  `is_damaged` tinyint(1) NOT NULL DEFAULT 0,
  `sync_texts` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'If true, delivery and return texts are synced',
  `answer_sync_map` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Maps answer index to sync status {0: true, 1: false}' CHECK (json_valid(`answer_sync_map`)),
  `question_id` bigint(20) UNSIGNED NOT NULL,
  `index_number` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

