--
-- Table structure for table `equipment_rental_ready_checklist_questions`
--

CREATE TABLE `equipment_rental_ready_checklist_questions` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `unique_id` char(36) NOT NULL,
  `equipment_rental_ready_template_id` bigint(20) UNSIGNED DEFAULT NULL,
  `rental_ready_checklist_questions_id` bigint(20) UNSIGNED DEFAULT NULL,
  `selected_answer_id` bigint(20) UNSIGNED DEFAULT NULL,
  `rental_ready_qa_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`rental_ready_qa_json`)),
  `general_notes` text DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

