--
-- Table structure for table `equipment_rental_ready_templates`
--

CREATE TABLE `equipment_rental_ready_templates` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `unique_id` char(36) NOT NULL,
  `equipment_id` bigint(20) UNSIGNED NOT NULL,
  `employee_id` bigint(20) UNSIGNED DEFAULT NULL,
  `employee_name` varchar(191) NOT NULL,
  `order_id` bigint(20) UNSIGNED DEFAULT NULL,
  `order_product_id` bigint(20) UNSIGNED DEFAULT NULL,
  `inspection_date` date NOT NULL,
  `inspection_time` time NOT NULL,
  `equipment_hours` decimal(8,1) DEFAULT NULL,
  `general_notes` text DEFAULT NULL,
  `status` enum('Draft','Rental Ready','Damaged') NOT NULL DEFAULT 'Draft',
  `is_complete` tinyint(1) NOT NULL DEFAULT 0,
  `total_questions` int(11) NOT NULL DEFAULT 0,
  `required_questions` int(11) NOT NULL DEFAULT 0,
  `optional_questions` int(11) NOT NULL DEFAULT 0,
  `required_items_completed` int(11) NOT NULL DEFAULT 0,
  `items_requiring_maintenance` int(11) NOT NULL DEFAULT 0,
  `damaged_items` int(11) NOT NULL DEFAULT 0,
  `created_by` bigint(20) UNSIGNED DEFAULT NULL,
  `updated_by` bigint(20) UNSIGNED DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

