(5, 'ORD-HIST-P0AO-MKTR', 1, NULL, 4, 'User', '2025-12-03 04:51:54', 'product_schedule_updated', 'Gary Jezorski updated product schedule (Pickup transport mode) for 3 Ton.', '{\"requested_data\":{\"type\":\"return\",\"pickup_transport_mode\":\"Truck\"},\"order_product\":{\"id\":1,\"unique_id\":\"ORD-SCH-BZUR-FQPL\",\"order_id\":1,\"product_id\":38,\"product_name\":\"3 Ton\",\"price\":\"344.00\",\"quantity\":1,\"hour_tracking\":\"Yes\",\"hour_rate\":\"57.00\",\"allocated_hours\":\"8.00\",\"sub_total\":\"392.00\",\"tax\":\"38.22\",\"total\":\"430.22\",\"product_data\":{\"product_unique_id\":\"PRO-VD0E-Z06T\",\"product_slug\":\"3-ton\",\"product_name\":\"3 Ton\",\"product_image_url\":\"https:\\/\\/staging.kabba.ai\\/storage\\/media\\/public_assets\\/2025\\/10\\/products\\/lqq3RG-media-3_ton_excavator_rental.webp\",\"product_type\":\"Rental\",\"product_variant\":\"daily\",\"product_sale_active\":false,\"product_price\":\"344.00\",\"quantity\":1,\"hour_tracking\":\"Yes\",\"hour_rate\":\"57.00\",\"allocated_hours\":8,\"service_method\":\"In Store Pickup\",\"distance_type\":null,\"distance_range\":null,\"service_option\":null,\"service_option_price\":0,\"store_address\":\"10296 High 46, Bon Aqua, Tennessee, 37025\",\"store_name\":\"Bon Aqua\",\"delivery_transport_mode\":\"Store\",\"delivery_store_id\":\"1\",\"delivery_date\":\"12\\/01\\/2025\",\"delivery_time\":\"09:00:00\",\"pickup_transport_mode\":\"Store\",\"pickup_store_id\":\"1\",\"pickup_date\":\"12\\/02\\/2025\",\"pickup_time\":\"09:00:00\",\"product_option_items\":[],\"product_rental_items\":[\"rental_damage_waiver\"],\"product_rental_items_prices\":{\"rental_damage_waiver\":48},\"sub_total\":392,\"tax\":38.219999999999998863131622783839702606201171875,\"total\":430.220000000000027284841053187847137451171875},\"service_method\":\"Delivery\",\"service_option\":\"Return Only\",\"distance_type\":null,\"distance_range\":null,\"delivery_status\":\"Pending\",\"delivery_transport_mode\":\"Store\",\"delivery_store_id\":1,\