CREATE TABLE `products` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `unique_id` varchar(191) NOT NULL,
  `product_name` varchar(191) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `product_type` enum('Rental','Retail') NOT NULL DEFAULT 'Retail',
  `seo_title` varchar(191) DEFAULT NULL,
  `seo_description` text DEFAULT NULL,
  `short_description` text DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `media_id` bigint(20) UNSIGNED DEFAULT NULL,
  `is_general_term_type` tinyint(1) NOT NULL DEFAULT 1,
  `is_custom_term_type` tinyint(1) NOT NULL DEFAULT 0,
  `sku` varchar(191) DEFAULT NULL,
  `barcode` varchar(191) DEFAULT NULL,
  `retail_price` decimal(8,2) DEFAULT NULL,
  `retail_sale_price` decimal(8,2) DEFAULT NULL,
  `retail_product_cost` decimal(8,2) DEFAULT NULL,
  `rental_daily` decimal(8,2) DEFAULT NULL,
  `rental_weekend` decimal(8,2) DEFAULT NULL,
  `rental_weekly` decimal(8,2) DEFAULT NULL,
  `rental_monthly` decimal(8,2) DEFAULT NULL,
  `rental_damage_waiver_daily` decimal(8,2) DEFAULT NULL,
  `rental_damage_waiver_weekend` decimal(8,2) DEFAULT NULL,
  `rental_damage_waiver_weekly` decimal(8,2) DEFAULT NULL,
  `rental_damage_waiver_monthly` decimal(8,2) DEFAULT NULL,
  `rental_track_insurance_daily` decimal(8,2) DEFAULT NULL,
  `rental_track_insurance_weekend` decimal(8,2) DEFAULT NULL,
  `rental_track_insurance_weekly` decimal(8,2) DEFAULT NULL,
  `rental_track_insurance_monthly` decimal(8,2) DEFAULT NULL,
  `rental_prepaid_cleaning` decimal(8,2) DEFAULT NULL,
  `rental_prepaid_fuel` decimal(8,2) DEFAULT NULL,
  `sale_price_daily` decimal(8,2) DEFAULT NULL,
  `sale_price_weekend` decimal(8,2) DEFAULT NULL,
  `sale_price_weekly` decimal(8,2) DEFAULT NULL,
  `sale_price_monthly` decimal(8,2) DEFAULT NULL,
  `standard_delivery_fee` decimal(8,2) DEFAULT NULL,
  `extended_delivery_fee` decimal(8,2) DEFAULT NULL,
  `in_store_pickup` enum('Yes','No') DEFAULT NULL,
  `delivery_and_pickup` enum('Yes','No') DEFAULT NULL,
  `hour_tracking` enum('Yes','No') DEFAULT NULL,
  `hour_rate` decimal(8,2) DEFAULT NULL,
  `is_default_funnel` tinyint(1) NOT NULL DEFAULT 0,
  `has_high_demand_alert` tinyint(1) NOT NULL DEFAULT 0,
